import{_ as r,o as a,c as i,a2 as c}from"./chunks/framework.DdtnLau3.js";const d=JSON.parse('{"title":"Service","description":"","frontmatter":{},"headers":[],"relativePath":"zh/concepts/service.md","filePath":"zh/concepts/service.md"}'),s={name:"zh/concepts/service.md"};function o(t,e,n,p,h,v){return a(),i("div",null,[...e[0]||(e[0]=[c('<h1 id="service" tabindex="-1">Service <a class="header-anchor" href="#service" aria-label="Permalink to &quot;Service&quot;">​</a></h1><p><strong>Service 提供 Work 中的实际能力</strong>。当前实现中，它是由 Core 管理、具有持久定义的应用容器。</p><p>Service 可以运行网页应用、数据库、本地 API 或其他运行进程。Harness 内部的工具不会自动成为 Service；Service 是受管理的应用资源。</p><h2 id="工作空间能做什么" tabindex="-1">工作空间能做什么 <a class="header-anchor" href="#工作空间能做什么" aria-label="Permalink to &quot;工作空间能做什么&quot;">​</a></h2><p>在 Kanban Work 中，看板 Service 提供界面和 API，数据可以保存在共享工作空间中。Harness 可以检查文件、修改应用、声明 Service，并检查它是否就绪。</p><p>应用仍然需要实际实现。仅有 Service 名称或部署请求，不等于应用已经正常运行。</p><h2 id="harness-如何操作-services" tabindex="-1">Harness 如何操作 Services <a class="header-anchor" href="#harness-如何操作-services" aria-label="Permalink to &quot;Harness 如何操作 Services&quot;">​</a></h2><p>Piwork 提供 Work 专属 Service 工具，支持创建、查看、更新、启动、停止、重启和读取日志。Core 执行 Docker 操作，并检查权限和配额。</p><p>Service 定义包含镜像、命令、环境变量、网络端口、工作空间访问和就绪检查。修改后，Harness 应使用返回的 Service ID 和 Operation ID 验证实际状态。</p><p>应用还可以为实验性 <code>piwork-brain</code> 包实现能力契约，以支持结构化查询和可验证操作。这需要额外的应用实现，并不是每个 HTTP 服务都自动具备的能力。</p><h2 id="默认-web-环境与更新" tabindex="-1">默认 Web 环境与更新 <a class="header-anchor" href="#默认-web-环境与更新" aria-label="Permalink to &quot;默认 Web 环境与更新&quot;">​</a></h2><p>使用当前默认 Brain 的新 Web 应用采用可复用的 FastAPI + React + TypeScript + Vite <a href="/piwork/zh/guide/web-development.html">Web base</a>，同时支持用户选择其他技术栈和维护已有应用。Harness 在修改后完成检查、构建、部署及实际版本验证；标准模板自动采用已就绪的更新，并保留支持恢复的草稿与路径。</p><p>应用 Service 不设置 Piwork 内存上限，也不预留 Service 内存；CPU/数量配额和 Agent/helper 内存政策继续有效。Agent 和 Web base 都提供 sqlite3 CLI，供获准的 workspace 开发与数据检查使用。</p><h2 id="访问和持久化" tabindex="-1">访问和持久化 <a class="header-anchor" href="#访问和持久化" aria-label="Permalink to &quot;访问和持久化&quot;">​</a></h2><p>Desktop 通过需要身份验证的本地应用入口提供已声明的 HTTP Services。从 Service 条目打开应用即可。</p><p>停止 Work 会停止运行容器，但保留 Service 定义和工作空间数据。启动 Work 会恢复已启用的 Services。单独停止一个 Service，会关闭它的运行意图，直到再次显式启动。</p><p>需要携带的应用数据应保存在 Work 托管存储中。容器临时层和外部数据库不会复制到 <code>.work</code> 归档。</p><p>当前定义和网络边界见 <a href="/piwork/zh/spec/service.html">Service 规范</a>。</p>',18)])])}const S=r(s,[["render",o]]);export{d as __pageData,S as default};
